/* =====================================================================================================
 * DMF0082 GET_MAIN_DATA 교체 · 90_VERIFY — 교체 확인 (조회 전용)
 * 마커 [E20261104-DMF0082ONEQUERY] · 생성 2026-11-09 14:03:13 (사내 ZIOUI1) · 실행 계정 = SCM_MGR · 파일 전체 F5 · 값 입력 없음
 * 교체 = PKG_DMF0082 의 P_DMF0082_GET_MAIN_DATA 구간 ← PKG_DMF0082_1104 의 같은 구간 (이 DB 의 USER_SOURCE 끼리 · 나머지 프로시저 무변경)
 * ===================================================================================================== */
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

-- V1 상태 — 기대 PACKAGE · PACKAGE BODY VALID
SELECT 'V1' CHK, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0082' ORDER BY OBJECT_TYPE;
-- V2 오류 — 기대 0
SELECT 'V2' CHK, COUNT(*) ERR_CNT, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END JUDGE FROM USER_ERRORS WHERE NAME = 'PKG_DMF0082';
-- V3 GET_MAIN_DATA 구간 = 사내 검증본(apply #26) — 기대 PASS
SELECT 'V3' CHK, X.N, X.L, X.H, CASE WHEN X.N = 16294 AND X.L = 922025 AND X.H = 35449467448126 THEN 'PASS'
            WHEN X.N = 16294 AND X.L = 922025 THEN 'PASS? (해시만 다름)' ELSE 'FAIL' END JUDGE
  FROM (WITH R AS (SELECT (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_GET_MAIN_DATA\s*(\(|$)')) L1,
                  (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_POPUP_GET_FUTUREPRICE_INFO(\s|\(|$)')) L2 FROM DUAL)
SELECT COUNT(*) N, NVL(SUM(LENGTH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))), 0) L, NVL(SUM(ORA_HASH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))), 0) H FROM USER_SOURCE S, R
 WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND S.LINE >= R.L1 AND S.LINE < R.L2 AND RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)) IS NOT NULL) X;
-- V4 구간 밖(다른 프로시저) 무변경 — 10 백업 때 지문과 같아야 PASS
SELECT 'V4' CHK, X.N, X.L, X.H, B.N BAK_N, B.L BAK_L, B.H BAK_H, CASE WHEN X.N = B.N AND X.L = B.L AND X.H = B.H THEN 'PASS' ELSE 'FAIL — 회신' END JUDGE
  FROM (WITH R AS (SELECT (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_GET_MAIN_DATA\s*(\(|$)')) L1,
                  (SELECT MIN(LINE) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND REGEXP_LIKE(TEXT, '^\s*PROCEDURE\s+P_DMF0082_POPUP_GET_FUTUREPRICE_INFO(\s|\(|$)')) L2 FROM DUAL)
SELECT COUNT(*) N, NVL(SUM(LENGTH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))), 0) L, NVL(SUM(ORA_HASH(RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)))), 0) H FROM USER_SOURCE S, R
 WHERE S.NAME='PKG_DMF0082' AND S.TYPE='PACKAGE BODY' AND (S.LINE < R.L1 OR S.LINE >= R.L2) AND RTRIM(TEXT, ' ' || CHR(9) || CHR(10) || CHR(13)) IS NOT NULL) X, ZB_DMF0082_GMD_FP B WHERE B.KIND = 'OUT';
-- V5 SPEC 무변경 · 권한 수 유지
SELECT 'V5' CHK, 'SPEC LAST_DDL' ITEM, TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') NOW_VAL, B.LAST_DDL BAK_VAL,
       CASE WHEN TO_CHAR(O.LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') = B.LAST_DDL THEN 'PASS' ELSE 'FAIL' END JUDGE
  FROM USER_OBJECTS O, ZB_DMF0082_GMD_BAK B WHERE O.OBJECT_NAME = 'PKG_DMF0082' AND O.OBJECT_TYPE = 'PACKAGE' AND B.OBJ_TYPE = 'PACKAGE'
UNION ALL
SELECT 'V5', 'GRANTS', TO_CHAR((SELECT COUNT(*) FROM USER_TAB_PRIVS_MADE WHERE TABLE_NAME = 'PKG_DMF0082')), TO_CHAR(F.N),
       CASE WHEN (SELECT COUNT(*) FROM USER_TAB_PRIVS_MADE WHERE TABLE_NAME = 'PKG_DMF0082') = F.N THEN 'PASS' ELSE 'FAIL' END
  FROM ZB_DMF0082_GMD_FP F WHERE F.KIND = 'GRANTS';
